/** Responsible Gaming lifecycle status shared by Risk-Control and Auth. */
export enum RgLifecycleStatus {
  RG_LIFECYCLE_UNSPECIFIED = 0,
  RG_ACTIVE = 1,
  /** RG_COOLING_OFF - F-06 冷静期 */
  RG_COOLING_OFF = 2,
  /** RG_SELF_EXCLUDED_TEMP - F-07 限期排除 */
  RG_SELF_EXCLUDED_TEMP = 3,
  /** RG_SELF_EXCLUDED_PERM - F-07 永久排除 */
  RG_SELF_EXCLUDED_PERM = 4,
  /** RG_CLOSED - F-09 注销 */
  RG_CLOSED = 5,
  UNRECOGNIZED = -1,
}

export function rgLifecycleStatusFromJSON(object: any): RgLifecycleStatus {
  switch (object) {
    case 0:
    case "RG_LIFECYCLE_UNSPECIFIED":
      return RgLifecycleStatus.RG_LIFECYCLE_UNSPECIFIED;
    case 1:
    case "RG_ACTIVE":
      return RgLifecycleStatus.RG_ACTIVE;
    case 2:
    case "RG_COOLING_OFF":
      return RgLifecycleStatus.RG_COOLING_OFF;
    case 3:
    case "RG_SELF_EXCLUDED_TEMP":
      return RgLifecycleStatus.RG_SELF_EXCLUDED_TEMP;
    case 4:
    case "RG_SELF_EXCLUDED_PERM":
      return RgLifecycleStatus.RG_SELF_EXCLUDED_PERM;
    case 5:
    case "RG_CLOSED":
      return RgLifecycleStatus.RG_CLOSED;
    case -1:
    case "UNRECOGNIZED":
    default:
      return RgLifecycleStatus.UNRECOGNIZED;
  }
}

export function rgLifecycleStatusToJSON(object: RgLifecycleStatus): string {
  switch (object) {
    case RgLifecycleStatus.RG_LIFECYCLE_UNSPECIFIED:
      return "RG_LIFECYCLE_UNSPECIFIED";
    case RgLifecycleStatus.RG_ACTIVE:
      return "RG_ACTIVE";
    case RgLifecycleStatus.RG_COOLING_OFF:
      return "RG_COOLING_OFF";
    case RgLifecycleStatus.RG_SELF_EXCLUDED_TEMP:
      return "RG_SELF_EXCLUDED_TEMP";
    case RgLifecycleStatus.RG_SELF_EXCLUDED_PERM:
      return "RG_SELF_EXCLUDED_PERM";
    case RgLifecycleStatus.RG_CLOSED:
      return "RG_CLOSED";
    case RgLifecycleStatus.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}

